function statPairRows(g){let [a,h]=sides(g);const ab=normAb(a.abbr),hb=normAb(h.abbr);const fromObj=o=>Object.entries(o||{}).map(([k,v])=>({k:String(k).replace(/([A-Z])/g,' $1').replace(/_/g,' ').trim().toUpperCase(),v:(v&&typeof v==='object')?(v.displayValue??v.value??'—'):v}));let as=metricRows(a.stats||g.away_stats||[]),hs=metricRows(h.stats||g.home_stats||[]);if(!as.length||!hs.length){const ts=g.team_stats||g.teamStats||{};if(!as.length)as=metricRows(ts[ab]||ts[a.abbr]||[])||[];if(!hs.length)hs=metricRows(ts[hb]||ts[h.abbr]||[])||[];if(!as.length&&ts[ab]&&typeof ts[ab]==='object')as=fromObj(ts[ab]);if(!hs.length&&ts[hb]&&typeof ts[hb]==='object')hs=fromObj(ts[hb])}const key=x=>String(x.k||'').toUpperCase().replace(/[^A-Z0-9]/g,'');let hm=new Map(hs.map(x=>[key(x),x.v]));let rows=as.filter(x=>hm.has(key(x))).map(x=>({k:x.k,a:num(x.v),h:num(hm.get(key(x))),ad:x.v,hd:hm.get(key(x))})).filter(x=>Number.isFinite(x.a)&&Number.isFinite(x.h));if(rows.length)return rows.slice(0,12);const scoreA=num(a.score),scoreH=num(h.score);return [{k:'SCORE',a:scoreA,h:scoreH,ad:String(a.score??0),hd:String(h.score??0)}]}
function compareBars44(rows,a,h){if(!rows.length)return '<div class="empty">Team comparison appears when the game feed returns comparable stats.</div>';return `<div class="compare44"><div class="vizTop"><span>TEAM COMPARISON</span><span>${esc(a)} ↔ ${esc(h)}</span></div>${rows.map(r=>{let mx=Math.max(Math.abs(r.a),Math.abs(r.h),1);return `<div class="compareRow44"><b>${esc(r.ad)}</b><i><em style="width:${Math.abs(r.a)/mx*50}%"></em><span>${esc(r.k)}</span><em style="width:${Math.abs(r.h)/mx*50}%"></em></i><b>${esc(r.hd)}</b></div>`}).join('')}</div>`}
async function gameGraphs44(){await Promise.all([ensure('teams'),ensure('games')]);let gs=S.games||[];if(!S.game)S.game=gs[0];let g=S.game;if(g?.id){try{g=await api('/api/game?id='+g.id,{ttl:6000,timeout:7000});S.game=g}catch{}}if(!g){shell('<main class="page"><div class="empty">Choose a game once the slate loads.</div></main>');return}let[a,h]=sides(g),plays=arr(g.plays),drives=arr(g.drives),pairs=statPairRows(g),q=[1,2,3,4].map(n=>({k:'Q'+n,v:plays.filter(p=>num(p.period)===n).length}));shell(`<main class="page graphs44"><section class="pageHero44 compact"><div><div class="eyebrow neonText">GAME GRAPHS</div><h1>The shape of<br><i>one game.</i></h1></div><label class="gameSelector44">SELECT GAME<select id="graphGame">${selectGameOptions(gs,g.id)}</select></label></section>${gamePickHero(g)}<section class="graphWall44"><article>${quarterChart(plays)}</article><article>${donut(q,'PLAY SHARE BY QUARTER')}</article><article>${compareBars44(pairs,normAb(a.abbr),normAb(h.abbr))}</article><article>${bars(q,'PLAYS BY QUARTER')}</article>${drives.length?`<article>${bars(drives.slice(-12).map((d,i)=>({k:'D'+(i+1),v:num(d.plays||d.play_count||0)})),'DRIVE LENGTH · PLAYS')}</article>`:''}</section><div class="truth44">Graphs only use data returned for this selected game. Missing play, drive or stat data stays missing.</div></main>`);document.querySelector('#graphGame').onchange=e=>{S.game=gs.find(x=>String(x.id)===String(e.target.value));gameGraphs44()}}
async function recap44(){await Promise.all([ensure('teams'),ensure('games')]);let proj={games:[]};try{proj=await api('/api/projections',{ttl:30000,timeout:7000,tries:0})}catch{}let fm=Object.fromEntries((proj.games||[]).map(x=>[String(x.id),x])),gs=S.games||[],finals=gs.filter(g=>g.completed||String(g.state||'').toLowerCase()==='post'||String(g.status||'').toLowerCase().startsWith('final'));let stories=finals.map(g=>gameStory(g,fm));let scored=finals.map(g=>{let[a,h]=sides(g),as=num(a.score),hs=num(h.score);return {g,a,h,total:as+hs,diff:Math.abs(as-hs)}});let closest=[...scored].sort((x,y)=>x.diff-y.diff)[0],highest=[...scored].sort((x,y)=>y.total-x.total)[0],biggest=[...scored].sort((x,y)=>y.diff-x.diff)[0];let feature=[closest,highest,biggest].filter((x,i,a)=>x&&a.findIndex(y=>String(y.g.id)===String(x.g.id))===i);shell(`<main class="page recap44"><section class="recapHero44"><div class="eyebrow neonText">WEEKLY RECAP</div><h1>The week,<br><i>in stories.</i></h1><p>Built from final scores, verified game state and ATLAS pregame context — not invented reporting.</p><div class="recapCount"><b>${finals.length}</b><span>FINALS CAPTURED</span></div></section><section class="storyFeatures44">${feature.map((x,i)=>{let st=gameStory(x.g,fm);let tag=String(x.g.id)===String(closest?.g.id)?'CLOSEST FINISH':String(x.g.id)===String(highest?.g.id)?'HIGHEST SCORING':'BIGGEST MARGIN';return `<button data-recap-game="${esc(x.g.id)}"><span>${tag}</span><h2>${esc(st.title)}</h2><small>${esc(st.detail)}</small><i>EXPLORE GAME ↗</i></button>`}).join('')||'<div class="empty">Weekly stories populate as games become final.</div>'}</section><section class="recapList44"><div class="sectionLead"><span>THE DESK</span><div><h2>Every final. Ranked by signal.</h2><p>Close finishes and forecast surprises rise naturally.</p></div></div>${stories.sort((a,b)=>b.priority-a.priority).map((x,i)=>`<button data-recap-game="${esc(x.g.id)}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(x.title)}</b><small>${esc(x.detail)}</small><i>↗</i></button>`).join('')||'<div class="empty">No completed games in the current slate yet.</div>'}</section></main>`);document.querySelectorAll('[data-recap-game]').forEach(x=>x.onclick=()=>{S.game=gs.find(g=>String(g.id)===String(x.dataset.recapGame));go('graphs')})}

// ATLAS 45 — Signal Engine: transparent, game-scoped performance ranking.
function impactValue(label,value){
  const k=String(label||'').toLowerCase(), v=num(value);
  if(!Number.isFinite(v)) return 0;
  if(/interception.*throw|int/.test(k)) return -2*v;
  if(/fumble.*lost/.test(k)) return -2*v;
  if(/touchdown|td/.test(k)) return 6*v;
  if(/sack/.test(k)) return 2.5*v;
  if(/tackle for loss|tfl/.test(k)) return 2*v;
  if(/interception/.test(k)) return 4*v;
  if(/pass.*yard/.test(k)) return v/25;
  if(/rush.*yard|receiv.*yard/.test(k)) return v/10;
  if(/reception|rec$/.test(k)) return v;
  if(/tackle/.test(k)) return .55*v;
  if(/pass.*def|pd$/.test(k)) return 1.5*v;
  if(/field goal/.test(k)) return 3*v;
  if(/extra point/.test(k)) return v;
  return 0;
}
function gamePerformers(g){
  const merged=new Map();
  arr(g.players).forEach(p=>{const key=String(p.id||`${p.name}|${p.team}`);let x=merged.get(key)||{id:p.id,name:p.name||'Unknown',team:normAb(p.team),position:p.position||'',raw:0,signals:[],categories:0};x.categories++;Object.entries(obj(p.stats)).forEach(([k,v])=>{let pts=impactValue(k,v);if(pts){x.raw+=pts;x.signals.push(`${k}: ${v}`)}});merged.set(key,x)});
  let rows=[...merged.values()].filter(x=>x.signals.length); if(!rows.length)return [];
  let lo=Math.min(...rows.map(x=>x.raw)),hi=Math.max(...rows.map(x=>x.raw)),span=hi-lo||1;
  return rows.map(x=>({...x,score:Math.round(20+80*(x.raw-lo)/span)})).sort((a,b)=>b.score-a.score);
}
function performanceBoard(g){let rows=gamePerformers(g);if(!rows.length)return `<div class="empty">ATLAS Impact activates when player box-score statistics are available for this game.</div>`;let top=rows.slice(0,5),low=[...rows].reverse().slice(0,5);let card=(x,i,tone)=>`<button class="impactPlayer ${tone}" ${x.id?`data-impact-player="${esc(x.id)}"`:''}><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(x.name)}</b><small>${esc(x.team)} · ${esc(x.position)} · ${esc(x.signals.slice(0,2).join(' · '))}</small></div><strong>${x.score}</strong></button>`;return `<div class="impactBoard45"><section><div class="impactHead45"><span>▲</span><div><b>BEST PERFORMANCES</b><small>Highest ATLAS statistical impact in this game</small></div></div>${top.map((x,i)=>card(x,i,'hot')).join('')}</section><section><div class="impactHead45 low"><span>▽</span><div><b>LOWEST IMPACT</b><small>Lowest measured box-score impact — not a player grade</small></div></div>${low.map((x,i)=>card(x,i,'cold')).join('')}</section></div>`}
function drivePulse45(drives){if(!drives?.length)return '<div class="empty">Drive pulse appears when drive data is returned.</div>';let rows=drives.slice(-16).map((d,i)=>({k:`D${i+1}`,v:num(d.plays||d.play_count||0)}));return `<div class="pulse45"><div class="vizTop"><span>DRIVE PULSE</span><span>PLAYS / DRIVE</span></div><div class="pulseBars45">${rows.map(x=>`<i title="${x.k}: ${x.v}" style="--v:${Math.max(8,Math.min(100,x.v*9))}%"><b></b><small>${x.k}</small></i>`).join('')}</div></div>`}

// Override the v44 graph room with a richer game-specific visual story.
