// ATLAS 47 — live field + recent-play rail.
function fieldSpot47(g){
  const s=g?.situation||{}, raw=String(s.yardLine||'').toUpperCase(), teams=(g?.teams||[]).map(t=>normAb(t.abbr));
  const m=raw.match(/\b([A-Z]{2,3})\s+(\d{1,2})\b/);
  if(!m)return {pct:null,label:raw&&raw!=='—'?raw:'BALL POSITION UNAVAILABLE'};
  const spot=normAb(m[1]), yd=Math.max(0,Math.min(50,+m[2]));
  const [away,home]=sides(g), aa=normAb(away.abbr),ha=normAb(home.abbr);
  let pct=spot===aa?yd:spot===ha?100-yd:null;
  return {pct,label:`${spot} ${yd}`};
}
function liveField47(g){
  const [a,h]=sides(g),s=g?.situation||{},spot=fieldSpot47(g),pos=normAb(s.possession), down=s.downDistanceText&&s.downDistanceText!=='—'?s.downDistanceText:(s.down!=='—'?`${s.down} & ${s.distance}`:'DOWN / DISTANCE UNAVAILABLE');
  return `<section class="liveField47"><div class="fieldTop47"><div><span>LIVE FIELD</span><b>${esc(pos||'POSSESSION —')}</b></div><div><strong>${esc(down)}</strong><small>${esc(spot.label)}</small></div></div><div class="fieldCanvas47" role="img" aria-label="Football field showing ${esc(spot.label)}"><div class="endzone47 away">${esc(normAb(a.abbr))}</div><div class="fieldLines47">${[10,20,30,40,50,40,30,20,10].map((x,i)=>`<i style="left:${(i+1)*10}%"><small>${x}</small></i>`).join('')}${spot.pct!=null?`<div class="ball47" style="left:${spot.pct}%"><b></b><span>${esc(spot.label)}</span></div>`:'<div class="noSpot47">FIELD POSITION NOT RETURNED</div>'}</div><div class="endzone47 home">${esc(normAb(h.abbr))}</div></div><div class="fieldFoot47"><span>${esc(pos&&pos!=='—'?pos+' BALL':'POSSESSION —')}</span><span>${esc(g.status||'')}</span></div></section>`;
}
function recentPlays47(g){let ps=(g?.plays||[]).slice(-10).reverse();return `<aside class="recentRail47"><div class="railHead47"><span>RECENT PLAYS</span><b>${ps.length?ps.length:'—'}</b></div><div class="playRail47">${ps.length?ps.map((p,i)=>`<article class="railPlay47 ${i===0?'latest':''}"><div><b>${esc(p.team||'—')}</b><span>Q${esc(p.period||'—')} · ${esc(p.clock||'—')}</span></div><p>${esc(p.text||'Play')}</p>${p.scoringPlay?'<small>SCORING PLAY</small>':''}</article>`).join(''):`<div class="empty">Recent plays appear here when the game feed returns play-by-play data.</div>`}</div></aside>`}
function fieldAndRail47(g){return `<section class="gameLive47">${liveField47(g)}${recentPlays47(g)}</section>`}

