// ATLAS 48 — NEON INTELLIGENCE / replay, stories, explainable impact, matchup DNA.
function story48(g){const [a,h]=sides(g),ps=g.plays||[],ds=g.drives||[],as=num(a.score),hs=num(h.score),events=[];ps.forEach((p,i)=>{let t=String(p.text||'');let w=0,tag='KEY PLAY';if(/touchdown/i.test(t)){w=9;tag='TOUCHDOWN'}else if(/intercept|fumble|turnover/i.test(t)){w=8;tag='TURNOVER'}else if(/fourth down/i.test(t)){w=6;tag='FOURTH DOWN'}else if(/field goal/i.test(t)){w=5;tag='FIELD GOAL'}else if(/sack/i.test(t)){w=4;tag='SACK'};if(w)events.push({i,w,tag,p})});events.sort((x,y)=>y.w-x.w);return {headline:`${normAb(a.abbr)} ${as} · ${normAb(h.abbr)} ${hs}`,events:events.slice(0,8),plays:ps,drives:ds}}
function momentum48(g){let ps=arr(g?.plays),pts=ps.map((p,i)=>{let t=String(p.text||''),v=0;if(/touchdown/i.test(t))v=7;else if(/field goal/i.test(t))v=3;else if(/intercept|fumble/i.test(t))v=-4;else if(/sack/i.test(t))v=-2;else if(/fourth down/i.test(t))v=2;return {k:i+1,v,txt:t}}).filter(x=>x.v);if(!pts.length)return '<div class="empty">Momentum markers appear when ATLAS receives scoring, turnover, sack or fourth-down plays.</div>';let max=Math.max(...pts.map(x=>Math.abs(x.v)),7);return `<div class="momentum48"><div class="vizTop"><span>MOMENTUM EVENTS</span><span>${pts.length} SIGNALS</span></div><div class="momTrack48">${pts.map(x=>`<button data-scrub48="${x.k-1}" title="${esc(x.txt)}" style="--x:${(x.k/Math.max(1,ps.length))*100}%;--v:${Math.abs(x.v)/max}"><i class="${x.v<0?'neg':''}"></i></button>`).join('')}</div><small>Scoring, turnovers, sacks and fourth-down events · click a marker to inspect that moment.</small></div>`}
function explainImpact48(g){let r=gamePerformers(g);if(!r.length)return '<div class="empty">Explainable ratings activate when player box-score data is available.</div>';return `<div class="explain48">${r.slice(0,8).map((x,i)=>`<article><span>#${i+1} · ${esc(x.team)} ${esc(x.position)}</span><h3>${esc(x.name)}</h3><b>${x.score}</b><p>${esc(x.signals.slice(0,4).join(' · ')||'Measured box-score production')}</p><small>ATLAS IMPACT · transparent statistical signal, not film grade</small></article>`).join('')}</div>`}
function replay48(g){let ps=g.plays||[];if(!ps.length)return '<div class="empty replayEmpty48">Replay activates when play-by-play is captured.</div>';return `<section class="replay48"><div class="sectionLead"><span>ATLAS REPLAY</span><div><h2>Rewind the game.</h2><p>Scrub the stored play sequence. Field context and play detail move with you.</p></div></div><input id="replaySlider48" type="range" min="0" max="${ps.length-1}" value="${ps.length-1}"><div id="replayRead48" class="replayRead48"></div></section>`}
function gameStoryPanel48(g){let s=story48(g);return `<section class="story48"><div class="sectionLead"><span>ATLAS GAME STORY</span><div><h2>${esc(s.headline)}</h2><p>The highest-signal moments ATLAS can establish from the captured play feed.</p></div></div><div class="storyRail48">${s.events.map((e,i)=>`<button data-story48="${e.i}"><span>${String(i+1).padStart(2,'0')} · ${e.tag}</span><b>Q${esc(e.p.period)} ${esc(e.p.clock)}</b><p>${esc(e.p.text||'Play')}</p></button>`).join('')||'<div class="empty">Game Story populates as key plays are captured.</div>'}</div></section>`}
function wireReplay48(g){let ps=g.plays||[],sl=document.querySelector('#replaySlider48'),read=document.querySelector('#replayRead48');let show=n=>{if(!read||!ps.length)return;let p=ps[Math.max(0,Math.min(ps.length-1,n))]||{};read.innerHTML=`<span>PLAY ${n+1} / ${ps.length}</span><b>Q${esc(p.period)} · ${esc(p.clock)} · ${esc(p.team||'')}</b><p>${esc(p.text||'Play')}</p>`;if(sl)sl.value=n};if(sl){sl.oninput=()=>show(+sl.value);show(+sl.value)}document.querySelectorAll('[data-story48],[data-scrub48]').forEach(b=>{b.onclick=()=>show(+(b.dataset.story48??b.dataset.scrub48))})}

