// ATLAS 50 — visual QA + deduplicated game intelligence.
function performersByTeam50(g){
  const [away,home]=sides(g), aa=normAb(away.abbr), hh=normAb(home.abbr), rows=gamePerformers(g);
  const bucket=ab=>rows.filter(x=>normAb(x.team)===ab);
  return {away,home,aa,hh,a:bucket(aa),h:bucket(hh),unknown:rows.filter(x=>![aa,hh].includes(normAb(x.team)))};
}
function teamImpact50(g){
  const d=performersByTeam50(g);
  if(!d.a.length&&!d.h.length){return `<div class="empty">ATLAS Impact is waiting for player box-score rows that identify the player's team.</div>`}
  const side=(team,ab,rows)=>`<section class="teamImpact50"><header><img src="${esc(team.logo||logo(ab))}"><div><span>${esc(ab)} PERFORMANCE</span><b>${esc(team.name||ab)}</b></div></header>${rows.length?rows.slice(0,6).map((x,i)=>`<button class="impactPlayer hot" ${x.id?`data-impact-player="${esc(x.id)}"`:''}><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(x.name)}</b><small>${esc(x.position)} · ${esc(x.signals.slice(0,2).join(' · '))}</small></div><strong>${x.score}</strong></button>`).join(''):`<div class="empty compact50">No identified ${esc(ab)} player rows returned for this game.</div>`}</section>`;
  return `<div class="impactBoard45 impactTeams50">${side(d.away,d.aa,d.a)}${side(d.home,d.hh,d.h)}</div>${d.unknown.length?`<div class="truth44">${d.unknown.length} player row${d.unknown.length===1?'':'s'} could not be assigned to either team, so ATLAS left them out instead of duplicating them.</div>`:''}`;
}
function explainImpact50(g){
 const d=performersByTeam50(g), rows=[...d.a.slice(0,4),...d.h.slice(0,4)];
 if(!rows.length)return '<div class="empty">Explainable ratings activate when team-tagged player box-score data is available.</div>';
 return `<div class="explain48 explain50">${rows.map(x=>`<article><span>${esc(x.team)} · ${esc(x.position)}</span><h3>${esc(x.name)}</h3><b>${x.score}</b><p>${esc(x.signals.slice(0,3).join(' · ')||'Measured box-score production')}</p><small>ATLAS IMPACT · statistical signal</small></article>`).join('')}</div>`;
}
