 const side=(team,ab,rows)=>`<section class="impactSide56" style="--team:${esc(teamTone56(ab))}"><header><img src="${esc(team.logo||logo(ab))}"><div><span>${esc(ab)} IMPACT</span><b>${esc(team.name||ab)}</b></div></header><div class="impactRows56">${rows.length?rows.slice(0,8).map((x,i)=>{let hs=playerHeadshot56(x);return `<button class="impactRow56" ${x.id?`data-impact-player="${esc(x.id)}"`:''}>${hs?`<img class="playerFace56" src="${esc(hs)}" alt="" onerror="this.style.display='none'">`:`<span class="faceFallback56">${esc((x.name||'?').split(' ').map(z=>z[0]).slice(0,2).join(''))}</span>`}<span class="impactRank56">${i+1}</span><div><b>${esc(x.name)}</b><small>${esc(x.position)} · ${esc(x.signals.slice(0,2).join(' · '))}</small></div><strong>${x.score}</strong></button>`}).join(''):`<div class="empty compact50">No ${esc(ab)} player rows.</div>`}</div></section>`;
 return `<div class="impactSplit56">${side(d.away,d.aa,d.a)}${side(d.home,d.hh,d.h)}</div>${d.unknown.length?`<div class="truth44">${d.unknown.length} unassigned player row${d.unknown.length===1?'':'s'} omitted instead of duplicated.</div>`:''}`;
