const ATLAS_BROWSER_BUILD='68.0';
async function syncAtlasBuild(){
  try{
    const r=await fetch('/api/build?sync='+Date.now(),{cache:'no-store',headers:{'Cache-Control':'no-cache'}});
    const b=await r.json(); const sv=String(b.version||'');
    if(sv && sv!==ATLAS_BROWSER_BUILD){
      const key='atlas-build-reload-'+sv;
      if(sessionStorage.getItem(key)!=='1'){
        sessionStorage.setItem(key,'1');
        const u=new URL(location.href); u.searchParams.set('_atlas_build',sv); location.replace(u.toString()); return;
      }
      let d=document.createElement('div'); d.className='buildMismatch';
      d.textContent=`ATLAS is finishing an update (browser ${ATLAS_BROWSER_BUILD} / server ${sv}).`;
      document.body.appendChild(d);
    } else if(sv){
      [...sessionStorage].filter(k=>String(k).startsWith('atlas-build-reload-')&&k!=='atlas-build-reload-'+sv).forEach(k=>sessionStorage.removeItem(k));
    }
  }catch{}
}
